let 시도 = 0;
function connect() {
  const ws = new WebSocket(URL);
  ws.onopen = () => { 시도 = 0; 따라잡기(); };
  ws.onclose = () => {
    const 기본 = Math.min(1000 * 2 ** 시도++, 30_000);   // 지수 백오프
    const 흔들기 = 기본 * (0.5 + Math.random() * 0.5);    // ← 이게 없으면 동시에 재접속
    setTimeout(connect, 흔들기);
  };
}

// 서버는 모든 변경에 증가하는 번호를 붙인다
// 클라는 마지막으로 받은 번호를 기억
ws.send({ type: 'resume', since: 마지막번호 });

// 서버: since 이후 변경을 몰아서 보낸다
//   너무 오래됐으면(로그가 없으면) "전체 다시 받기" 로 강등
